    "module": { "type": "string", "description": "The poly module the adapter loads." },
    "instances": {
      "type": "object",
      "description": "Each instance the host creates, by name: its machine, and whether it is created at start or by a method (keyed by one of that method's arguments).",
      "additionalProperties": {
        "type": "object",
        "required": ["machine"],
        "additionalProperties": false,
        "properties": {
          "machine": { "type": "string" },
          "createdBy": { "type": "string", "description": "A method name; absent for an instance created when the host is created." },
