import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../build/host.gen.ts';

test('lifecycle', async () => {
  const h = await create();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, false);
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1, votedFor: 'itself' });
  assert.deepEqual(await h.electionWon(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'leader', term: 1, votedFor: 'itself' });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.quorumLost(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'itself' });
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.equal((await h.newerTermSeen(4)).ok, false);
  assert.equal((await h.newerTermSeen(0)).ok, false);
  assert.deepEqual(await h.newerTermSeen(3), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 3, votedFor: 'nobody' });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.shutdown(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 3, votedFor: 'nobody' });
  assert.equal((await h.shutdown()).ok, false);
  assert.equal((await h.newerTermSeen(3)).ok, false);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 3, votedFor: 'nobody' });
});

test('votes', async () => {
  const h = await create();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
  assert.equal((await h.voteRequested('n3', 1)).ok, false);
  assert.equal((await h.voteRequested('n1', 0)).ok, false);
  assert.equal((await h.voteRequested('n1', 4)).ok, false);
  assert.equal((await h.voteRequested('zz', 1)).ok, false);
  assert.deepEqual(await h.voteRequested('n1', 1), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'n1' });
  assert.deepEqual(await h.voteRequested('n1', 1), { ok: true });
  assert.equal((await h.voteRequested('n2', 1)).ok, false);
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 2, votedFor: 'itself' });
  assert.equal((await h.voteRequested('n2', 2)).ok, false);
  assert.equal((await h.voteRequested('n2', 1)).ok, false);
  assert.deepEqual(await h.newerTermSeen(3), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 3, votedFor: 'nobody' });
  assert.deepEqual(await h.voteRequested('n2', 3), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 3, votedFor: 'n2' });
  await h.shutdown();
  assert.equal((await h.voteRequested('n2', 3)).ok, false);
});

test('leader steps down on newer vote request', async () => {
  const h = await create();
  await h.electionTimeout();
  await h.electionWon();
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  assert.deepEqual(await h.voteRequested('n1', 2), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'n1' });
});

test('election lost', async () => {
  const h = await create();
  assert.equal((await h.electionLost()).ok, false);
  await h.electionTimeout();
  assert.deepEqual(await h.electionLost(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'itself' });
  assert.equal((await h.electionLost()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  assert.deepEqual(await h.voteRequested('n1', 2), { ok: true });
  const h2 = await create();
  await h2.electionTimeout();
  await h2.electionWon();
  assert.equal((await h2.electionLost()).ok, false);
});

test('out-of-domain term refused', async () => {
  const h = await create();
  assert.equal((await h.newerTermSeen(99)).ok, false);
  assert.equal((await h.newerTermSeen(-5)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
});

