import createHost from '../build/host.gen.ts';

// Wraps node() so the older assertions check only the fields they name; `paused` is checked in its own test.
async function create() {
  const h = await createHost();
  return Object.assign(Object.create(h), {
    node: async () => { const { paused, ...rest } = await h.node(); return rest; },
    full: () => h.node(),
  });
}

test('pause', async () => {
  const h = await create();
  assert.deepEqual(await h.full(), { role: 'follower', term: 0, votedFor: 'nobody', paused: false });
  assert.equal((await h.resume()).ok, false);
  assert.deepEqual(await h.pause(), { ok: true });
  assert.equal((await h.pause()).ok, false);
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.voteRequested('n1', 1), { ok: true });
  assert.deepEqual(await h.full(), { role: 'follower', term: 1, votedFor: 'n1', paused: true });
  assert.deepEqual(await h.newerTermSeen(2), { ok: true });
  assert.deepEqual(await h.full(), { role: 'follower', term: 2, votedFor: 'nobody', paused: true });
  assert.deepEqual(await h.resume(), { ok: true });
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.equal((await h.pause()).ok, false);
  await h.electionWon();
  assert.equal((await h.pause()).ok, false);
  assert.deepEqual(await h.full(), { role: 'leader', term: 3, votedFor: 'itself', paused: false });
  const h2 = await create();
  await h2.pause();
  await h2.shutdown();
  assert.equal((await h2.resume()).ok, false);
});

